const https = require\('https'\);
const fs = require\('fs'\);

function fetchJson\(url\) {
  return new Promise\(\(resolve, reject\) => {
    https.get\(url, { headers: { 'User-Agent': 'magic-draft-app/1.0' } }, res => {
