const https = require\('https'\);
const fs = require\('fs'\);

function fetchJson\(url\) {
  return new Promise\(\(resolve, reject\) => {
    const options = {
      headers: {
        'User-Agent': 'MagicDraftApp/1.0 \(contact@example.com\)',
        'Accept': 'application/json'
      }
    };
    https.get\(url, options, res => {
      let data = '';
      res.on\('data', d => data += d\);
      res.on\('end', \(\) => {
        try { resolve\(JSON.parse\(data\)\); } catch\(e\) { reject\(new Error\('Parse fail: ' + data.slice\(0,200\)\)\); }
      }\);
    }\).on\('error', reject\);
  }\);
}

async function downloadTDM\(\) {
  let allCards = [];
  let url = 'https://api.scryfall.com/cards/search?q=set:tdm&unique=cards&order=set';
  let page = 1;
  while \(url\) {
    process.stdout.write\('Page ' + page + '... '\);
    const data = await fetchJson\(url\);
    if \(data.error || data.object === 'error'\) { console.log\('Error:', data.details\); break; }
    allCards = allCards.concat\(data.data\);
    console.log\('got', data.data.length, 'cards'\);
    url = data.has_more ? data.next_page : null;
    page++;
    if \(url\) await new Promise\(r => setTimeout\(r, 150\)\);
  }
  const out = { set: 'TDM', total: allCards.length, cards: allCards };
  fs.writeFileSync\('public/data/scryfall-tdm.json', JSON.stringify\(out\)\);
  console.log\('Saved', allCards.length, 'cards,', \(fs.statSync\('public/data/scryfall-tdm.json'\).size/1024/1024\).toFixed\(1\), 'MB'\);
}
downloadTDM\(\).catch\(console.error\);
